--
-- Name: v_dashboard_day; Type: VIEW; Schema: bill; Owner: -
--

CREATE VIEW bill.v_dashboard_day AS
 SELECT business_day,
    sum(gross) AS gross,
    sum(discount) AS discount,
    sum(net) AS net,
    sum(due_created) AS due_created,
    sum(due_collected) AS due_collected,
    sum(refunds) AS refunds,
    sum(variance) AS variance,
    count(*) AS sessions
   FROM ( SELECT DISTINCT ON (day_close_summary.counter_session_id) day_close_summary.id,
            day_close_summary.branch_id,
            day_close_summary.counter_session_id,
            day_close_summary.business_day,
            day_close_summary.dept_split,
            day_close_summary.tender_totals,
            day_close_summary.gross,
            day_close_summary.discount,
            day_close_summary.net,
            day_close_summary.due_created,
            day_close_summary.due_collected,
            day_close_summary.refunds,
            day_close_summary.variance,
            day_close_summary.version,
            day_close_summary.supersedes
           FROM bill.day_close_summary
          ORDER BY day_close_summary.counter_session_id, day_close_summary.version DESC) latest
  GROUP BY business_day;


